import {systemsLessons} from './systems-curriculum.js';
import {computerLessons} from './computer-curriculum.js';
import {databaseLessons} from './database-curriculum.js';

export const topicCatalog=[
 {slug:'ai',title:'AI & deep learning',label:'Artificial intelligence',description:'Explore how neural networks represent information, learn patterns, and generate something new.',count:1,first:'transformers'},
 {slug:'distributed-systems',title:'Distributed systems',label:'Software engineering',description:'Reason about coordination, data, scale, and failure. Build systems whose promises survive the real world.',count:systemsLessons.length,experiments:systemsLessons.reduce((n,l)=>n+l.chapters.length,0),first:systemsLessons[0].slug},
 {slug:'computer-systems',title:'Computer systems & performance',label:'Software engineering',description:'Follow code through the machine. Explore execution, memory, concurrency, I/O, and the evidence behind useful optimization.',count:computerLessons.length,experiments:computerLessons.reduce((n,l)=>n+l.chapters.length,0),first:computerLessons[0].slug},
 {slug:'database-internals',title:'Database internals',label:'Software engineering',description:'Look beneath SQL: pages, indexes, query plans, transactions, and the machinery that keeps data recoverable.',count:databaseLessons.length,experiments:databaseLessons.reduce((n,l)=>n+l.chapters.length,0),first:databaseLessons[0].slug}
];

export function systemsMotif(){return `<svg viewBox="0 0 540 270" class="diagram" role="img" aria-label="Three regions connected by replication links"><g fill="none" stroke="#78aec3"><path class="path-line" d="M125 95L270 205L420 95Z"/><path d="M125 95L270 45L420 95" opacity=".4"/></g>${[[125,95,'Region A'],[420,95,'Region B'],[270,205,'Region C']].map(([x,y,t],i)=>`<rect x="${x-52}" y="${y-25}" width="104" height="50" rx="7" fill="#1b2931" stroke="#86bfd4"/><text x="${x}" y="${y+5}" text-anchor="middle" class="blue">${t}</text>`).join('')}<text x="270" y="125" text-anchor="middle" class="bright">replicate · coordinate</text><text x="270" y="150" text-anchor="middle">survive a broken link</text></svg>`;}

export function computerMotif(){return `<svg viewBox="0 0 540 270" class="diagram" role="img" aria-label="A CPU core connects through caches to memory and I/O"><g fill="none" stroke="#c39a6e" stroke-width="2"><path class="path-line" d="M160 135H235M305 135H385M270 90V48M270 180V222"/><path d="M75 80V65H145V80M75 190V205H145V190" opacity=".4"/></g><rect x="55" y="85" width="110" height="100" rx="9" fill="#352b20" stroke="#edbd85"/><text x="110" y="130" text-anchor="middle" style="fill:#edbd85">CPU core</text><text x="110" y="153" text-anchor="middle">execute</text><rect x="230" y="90" width="80" height="90" rx="7" fill="#25323a" stroke="#91cce2"/><text x="270" y="130" text-anchor="middle" class="blue">Cache</text><text x="270" y="153" text-anchor="middle">reuse</text><rect x="385" y="85" width="110" height="100" rx="9" fill="#292538" stroke="#b6a6df"/><text x="440" y="130" text-anchor="middle" style="fill:#b6a6df">Memory</text><text x="440" y="153" text-anchor="middle">store</text><text x="270" y="35" text-anchor="middle">instructions ↓</text><text x="270" y="245" text-anchor="middle">↓ kernel · I/O · waiting</text></svg>`;}

export function databaseMotif(){return `<svg viewBox="0 0 540 270" class="diagram" role="img" aria-label="An ordered database index leads to three leaf pages above a durable write-ahead log"><g fill="none" stroke="#96d4b3" stroke-width="2"><path class="path-line" d="M270 80L125 145M270 80V145M270 80L415 145"/><path d="M172 165H222M317 165H367" stroke-dasharray="4 4"/><path d="M125 190V225H415V190" opacity=".5"/></g><rect x="215" y="30" width="110" height="50" rx="7" fill="#284333" stroke="#96d4b3"/><text x="270" y="60" text-anchor="middle" style="fill:#c5ebd3">20 | 40</text>${[[125,'04 · 12'],[270,'20 · 35'],[415,'40 · 62']].map(([x,label])=>`<rect x="${x-48}" y="145" width="96" height="44" rx="6" fill="#203331" stroke="#96d4b3"/><text x="${x}" y="172" text-anchor="middle" style="fill:#b5dfd6">${label}</text>`).join('')}<rect x="170" y="214" width="200" height="29" rx="4" fill="#302a20" stroke="#b29468"/><text x="270" y="234" text-anchor="middle" style="fill:#edbd85">write-ahead log</text><text x="270" y="115" text-anchor="middle">seek · scan · recover</text></svg>`;}

export function renderCatalog(app,{base,aiTopic,header,aiMotif}){
 const topic=base+'topics/ai/',lesson=topic+'transformers/';
 app.innerHTML=header()+`<main id="main" class="library"><div class="eyebrow accent">${aiTopic?'Topic 01 / Artificial intelligence':`The library / ${topicCatalog.length} topics`}</div><div class="library-heading"><h1>${aiTopic?'AI & deep<br><span class="accent">learning.</span>':'Big ideas.<br><span class="accent">Within reach.</span>'}</h1><p>${aiTopic?'Explore the mechanisms behind models that learn, generate, and reason.':'Learn by changing things.<br>Visual lessons for ideas worth understanding deeply.'}</p></div>${aiTopic?`<div class="section-line"><h3>Explore the lessons</h3><small>01 lesson</small></div><a class="lesson-card" href="${lesson}"><span class="lesson-number">01</span><div><span class="eyebrow accent">Interactive lesson · 11 chapters</span><h2 style="margin-top:9px">Inside the transformer</h2><p>From your first attention head to the architectures of 2026.</p></div><span class="pill">Open lesson</span></a>`:`<div class="section-line"><h3>Browse by topic</h3><small>${topicCatalog.reduce((n,t)=>n+t.count,0)} lessons</small></div><div class="catalog-topics">${topicCatalog.map((t,i)=>`<div class="topic-card"><div class="topic-info"><span class="eyebrow accent">${String(i+1).padStart(2,'0')} / ${t.label}</span><h2>${t.title}</h2><p>${t.description}</p><a class="btn primary" href="${base}topics/${t.slug}/">Explore topic</a><small>${t.count} ${t.count===1?'lesson':'lessons'}${t.experiments?' · '+t.experiments+' interactive experiments':''}</small></div><a href="${base}topics/${t.slug}/${t.first}/" class="topic-art" aria-label="Open the first ${t.title} lesson">${t.slug==='ai'?aiMotif():t.slug==='distributed-systems'?systemsMotif():t.slug==='computer-systems'?computerMotif():databaseMotif()}</a></div>`).join('')}</div>`}<footer class="library-foot"><span>Fieldnotes / Understand through interaction.</span><span>Less reading. More seeing.</span></footer></main>`;
}
